from pathlib import Path
import hashlib, re, shutil

OUT=Path('outputs/uni_tehran/review/md')
RAW=Path('متن ها/uni_tehran/md')
FINAL=Path('final/uni-tehran')
REPORT=Path('reports/uni_tehran_finalization.md')

BAD=['دقدقه','محارت','دوچار','تلاتوم','ناعتمین','کس با کار','ثواد','اسطلاح','ازترار','زخیره','بورت','سهان','سحام','صحام','قرد','نقض شوند','خیش فرمای','پجوه','پجوش','ترراحی','نوستان','تشقیص','حدررفت','انترنت','رمزرز','رمزرس','خانابد','ثبتگردان','معلف','جامپستار','جامپسار','گذینه','کنترول','مرفع','بیس سال','دویتر','برارت زمانه','نبو و','نوت درصد']

def sha(s): return hashlib.sha256(s.encode()).hexdigest()
def apply(text, old, new, label, changes):
    n=text.count(old)
    assert n==1, f'{label}: expected 1 match, got {n}'
    changes.append(label)
    return text.replace(old,new,1)

assert sorted(int(p.stem) for p in OUT.glob('*.md') if p.stem.isdigit()) == list(range(1,39))
assert sorted(int(p.stem) for p in RAW.glob('*.md') if p.stem.isdigit()) == list(range(1,39))
FINAL.mkdir(parents=True,exist_ok=True)
for p in FINAL.glob('*.md'): p.unlink()

