# validation
files=sorted(FINAL.glob('episode-*.md'))
assert len(files)==38
for ep,p in enumerate(files,1):
    t=p.read_text(encoding='utf-8')
    assert '[نامفهوم]' not in t
    for bad in BAD: assert bad not in t, (ep,bad)
    mother=(OUT/f'{ep}.md').read_text(encoding='utf-8')
    if ep!=4: assert t==mother, f'episode {ep} changed unexpectedly'
assert len(changes)==9

